CREATE TABLE IF NOT EXISTS films (id TEXT PRIMARY KEY NOT NULL, body TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS app_settings (name TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enrichment_snapshots (id TEXT PRIMARY KEY, body TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lists (id TEXT PRIMARY KEY NOT NULL, body TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS notices (id TEXT PRIMARY KEY NOT NULL, body TEXT NOT NULL, created INTEGER NOT NULL, read INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS notices_created ON notices(created);
CREATE TABLE IF NOT EXISTS watch_checks (record_id TEXT PRIMARY KEY NOT NULL, body TEXT NOT NULL, checked_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trash (id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL, item_id TEXT NOT NULL, body TEXT NOT NULL, revision INTEGER NOT NULL, deleted_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS trash_deleted ON trash(deleted_at);
CREATE TABLE IF NOT EXISTS backups (id TEXT PRIMARY KEY NOT NULL, created INTEGER NOT NULL, kind TEXT NOT NULL, size INTEGER NOT NULL, chunks INTEGER NOT NULL, summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS backup_chunks (backup_id TEXT NOT NULL, idx INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (backup_id, idx));
